#!/usr/bin/env node
"use strict";
// EXT-VERIFY-001 E2E-008: two simultaneous live dispatches and independent byte readback.
const cp=require("node:child_process"),fs=require("node:fs"),os=require("node:os"),path=require("node:path"),crypto=require("node:crypto");
const REPO="BestNameYet/Terminals",WF="chatgpt-shared-conversation-extractor.yml";
const SOURCES=[
"https://chatgpt.com/share/6ae9dd85-7ff0-83e8-90c3-4592305a2362",
"https://chatgpt.com/share/6ae8ca4c-fde8-83e8-991c-f6beaed35051"];
const FILES=["response.html","conversation-raw.json","linear-conversation.json","conversation.json","conversation.md","diagnostics.json","receipt.json","execution.json"];
const unique="e2e008-"+process.env.GITHUB_RUN_ID+"-"+Date.now();
const report={schema:"terminals.e2e008.evidence.v1",test_id:"E2E-008",requirement_id:"EXT-FR-070",status:"RUNNING",started_at:new Date().toISOString(),nonce:unique,sources:SOURCES,checks:[],runs:[],errors:[]};
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
function check(condition,name,detail=""){if(!condition)throw Error(name+": "+detail);report.checks.push(name);}
function exec(cmd,args,opt={}){const r=cp.spawnSync(cmd,args,{encoding:opt.binary?null:"utf8",timeout:opt.timeout||70000,maxBuffer:80*1024*1024});if(r.error||r.status!==0)throw Error(cmd+" "+args[0]+" failed: "+String(r.stderr||r.error).slice(0,500));return r.stdout;}
function api(url){return JSON.parse(exec("gh",["api",url]));}
function submit(request){return new Promise((resolve,reject)=>{const p=cp.spawn("gh",["workflow","run",WF,"-R",REPO,"-r","main","--raw-field","request_json="+JSON.stringify(request)]);let e="";p.stderr.on("data",b=>e+=b);p.on("error",reject);p.on("close",c=>c===0?resolve(true):reject(Error("dispatch failure: "+e.slice(0,500))));});}
function readReceipt(run,uuid){try{const f=api("repos/"+REPO+"/contents/workspaces/shared-conversations/"+uuid+"/"+run.id+"-"+run.run_attempt+"/receipt.json");return JSON.parse(Buffer.from(f.content.replace(/\s/g,""),"base64").toString("utf8"));}catch{return null;}}
function remote(file){return exec("git",["show","refs/remotes/origin/main:"+file],{binary:true});}
async function main(){
try{
const uuid=s=>{const u=new URL(s);check(u.protocol==="https:"&&u.hostname==="chatgpt.com"&&!u.port&&!u.username&&!u.hash&&/^\/share\/[a-f0-9-]{36}$/.test(u.pathname),"valid-source");return u.pathname.slice(7);};
const requests=SOURCES.map((u,i)=>({target_url:u,request_id:unique+"-"+i,export_profile:"complete",share_uuid:uuid(u)}));
check(requests[0].share_uuid!==requests[1].share_uuid,"distinct-source-shares");
const started=Date.now(),startCutoff=started-20000;
await Promise.all(requests.map(r=>{const {share_uuid,...request}=r;return submit(request);}));
check(Date.now()-started<45000,"near-simultaneous-dispatch");
report.dispatches=requests.map(r=>({request_id:r.request_id,share_uuid:r.share_uuid}));
const found=new Map(),deadline=Date.now()+225000;let candidates=[];
while(Date.now()<deadline&&found.size<2){
const all=api("repos/"+REPO+"/actions/workflows/"+WF+"/runs?event=workflow_dispatch&per_page=100").workflow_runs;
check(Array.isArray(all),"workflow-run-list");
candidates=all.filter(r=>Date.parse(r.created_at)>=startCutoff);
for(const r of candidates){if(r.status!=="completed"||r.conclusion!=="success")continue;
for(const req of requests){if(found.has(req.request_id))continue;
const receipt=readReceipt(r,req.share_uuid);
if(receipt&&receipt.request_id===req.request_id){found.set(req.request_id,{run:r,req,receipt});}}}
if(found.size<2)await new Promise(resolve=>setTimeout(resolve,7500));
}
report.candidate_runs=candidates.map(r=>({id:r.id,status:r.status,conclusion:r.conclusion}));
check(found.size===2,"both-correlated-by-request-id",String(found.size));
const pair=requests.map(q=>found.get(q.request_id));
check(pair[0].run.id!==pair[1].run.id,"distinct-run-ids");
check(Math.abs(Date.parse(pair[0].run.created_at)-Date.parse(pair[1].run.created_at))<60000,"close-created-times");
exec("gh",["auth","setup-git"]);
exec("git",["fetch","origin","+refs/heads/main:refs/remotes/origin/main"],{timeout:120000});
report.remote_head=exec("git",["rev-parse","refs/remotes/origin/main"]).trim();
for(const {run,req,receipt} of pair){
const base="workspaces/shared-conversations/"+req.share_uuid+"/"+run.id+"-"+run.run_attempt;
check(run.conclusion==="success","run-success-"+run.id);
check(receipt.write_path===base&&String(receipt.run_id)===String(run.id),"receipt-identity-"+run.id);
check(receipt.source_url===req.target_url&&receipt.share_uuid===req.share_uuid,"receipt-source-"+run.id);
check(receipt.methods.includes("source-linear-v1")&&receipt.methods.includes("selected-parent-chain-v1"),"both-extractors-"+run.id);
const tree=exec("git",["ls-tree","-r","--name-only","refs/remotes/origin/main","--",base]).trim().split("\n").filter(Boolean).map(s=>s.slice(base.length+1)).sort();
check(JSON.stringify(tree)===JSON.stringify([...FILES].sort()),"exactly-eight-files-"+run.id);
const dir=fs.mkdtempSync(path.join(os.tmpdir(),"attestation-"));let att;
try{exec("gh",["run","download",String(run.id),"-R",REPO,"-n","chatgpt-shared-export-final-attestation-"+run.id+"-"+run.run_attempt,"-D",dir]);att=JSON.parse(fs.readFileSync(path.join(dir,"final-attestation.json"),"utf8"));}finally{fs.rmSync(dir,{recursive:true,force:true});}
check(att.verification==="VERIFIED"&&String(att.run_id)===String(run.id)&&att.request_id===req.request_id,"attestation-identity-"+run.id);
check(att.paths.length===8,"attestation-complete-"+run.id);
const expected=new Map(att.paths.map(f=>[f.path,f])),proof={};
for(const name of FILES){const full=base+"/"+name,b=remote(full),hash=sha(b),a=expected.get(full);
check(!!a&&a.sha256===hash&&a.bytes===b.length&&a.matched_remote_bytes===true,"remote-sha256-"+run.id+"-"+name);
if(receipt.files?.[name])check(receipt.files[name].sha256===hash&&receipt.files[name].bytes===b.length,"receipt-sha256-"+run.id+"-"+name);
proof[name]={bytes:b.length,sha256:hash};}
const commits=exec("git",["log","refs/remotes/origin/main","--format=%H","--grep","^Export complete shared conversation "+run.id+"-"+run.run_attempt+"$"]).trim().split("\n");
check(commits.includes(att.published_commit_sha),"published-commit-reachable-"+run.id);
report.runs.push({id:run.id,url:run.html_url,request_id:req.request_id,created_at:run.created_at,conclusion:run.conclusion,output_path:base,published_commit:att.published_commit_sha,files:proof,counts:receipt.counts});
}
check(new Set(report.runs.map(r=>r.output_path)).size===2,"no-overwritten-paths");
check(new Set(report.runs.map(r=>r.published_commit)).size===2,"no-lost-publication-commits");
report.status="PASS";
}catch(e){report.status="FAIL";report.errors.push(String(e.message||e).slice(0,1200));}
report.finished_at=new Date().toISOString();
const dest="workspaces/extractor-srs-design/acceptance/results/E2E-008-"+unique+".json";
fs.mkdirSync(path.dirname(dest),{recursive:true});
const body=Buffer.from(JSON.stringify(report,null,2)+"\n");
fs.writeFileSync(dest,body);
try{exec("gh",["api","--method","PUT","repos/"+REPO+"/contents/"+dest,"-f","message=E2E-008 concurrent export "+report.status,"-f","content="+body.toString("base64")]);
const saved=api("repos/"+REPO+"/contents/"+dest);check(Buffer.from(saved.content.replace(/\s/g,""),"base64").equals(body),"evidence-readback");
}catch(e){report.status="FAIL";report.errors.push("evidence publication: "+String(e.message||e).slice(0,300));}
console.log(JSON.stringify({status:report.status,test_id:"E2E-008",checks:report.checks.length,run_ids:report.runs.map(r=>r.id),paths:report.runs.map(r=>r.output_path),evidence:dest,errors:report.errors}));
if(report.status!=="PASS")process.exitCode=1;
}
main().catch(e=>{console.log(JSON.stringify({status:"FAIL",error:String(e.message||e)}));process.exitCode=1;});

E2E008_NODE_SOURCE
node --check workspaces/extractor-srs-design/acceptance/e2e-008-concurrent-exports.js
